import 'package:flutter/cupertino.dart';
import 'package:flutter/material.dart';

class KitTheme {
 static const blue=Color(0xff0088ff),darkBlue=Color(0xff0091ff),red=Color(0xffff383c),green=Color(0xff34c759);
 static ThemeData light()=>ThemeData(useMaterial3:true,brightness:Brightness.light,colorScheme:ColorScheme.fromSeed(seedColor:blue),scaffoldBackgroundColor:const Color(0xfff2f2f7));
 static ThemeData dark()=>ThemeData(useMaterial3:true,brightness:Brightness.dark,colorScheme:ColorScheme.fromSeed(seedColor:darkBlue,brightness:Brightness.dark),scaffoldBackgroundColor:Colors.black);
}
enum KitButtonSize {small,medium,large}
enum KitButtonAppearance {prominent,tinted,plain,glass}
class KitButton extends StatelessWidget {
 final String label;final VoidCallback? onPressed;final KitButtonSize size;final KitButtonAppearance appearance;final bool destructive,loading;final Widget? icon;
 const KitButton({super.key,required this.label,this.onPressed,this.size=KitButtonSize.large,this.appearance=KitButtonAppearance.prominent,this.destructive=false,this.loading=false,this.icon});
 @override Widget build(BuildContext context){final dark=Theme.of(context).brightness==Brightness.dark;final accent=destructive?KitTheme.red:dark?KitTheme.darkBlue:KitTheme.blue;final prominent=appearance==KitButtonAppearance.prominent;final background=prominent?accent:appearance==KitButtonAppearance.tinted?accent.withValues(alpha:.14):appearance==KitButtonAppearance.glass?(dark?const Color(0xff333336):Colors.white.withValues(alpha:.8)):null;final font=size==KitButtonSize.large?17.0:size==KitButtonSize.medium?15.0:13.0;return CupertinoButton(onPressed:loading?null:onPressed,color:background,disabledColor:accent.withValues(alpha:.2),borderRadius:BorderRadius.circular(1000),minimumSize:Size(0,size==KitButtonSize.large?50:size==KitButtonSize.medium?34:28),padding:EdgeInsets.symmetric(horizontal:size==KitButtonSize.large?20:12,vertical:size==KitButtonSize.large?14:4),child:Row(mainAxisSize:MainAxisSize.min,children:[if(loading)const CupertinoActivityIndicator()else if(icon!=null)icon!,if(loading||icon!=null)const SizedBox(width:4),Text(label,style:TextStyle(fontSize:font,height:22/font,letterSpacing:-.43,color:prominent?Colors.white:accent))]));}
}
class KitToggle extends StatelessWidget {
 final bool value;final ValueChanged<bool>? onChanged;final String label;
 const KitToggle({super.key,required this.value,required this.onChanged,required this.label});
 @override Widget build(BuildContext context)=>Semantics(label:label,child:CupertinoSwitch(value:value,onChanged:onChanged,activeTrackColor:KitTheme.green));
}
class KitTextField extends StatelessWidget {
 final String label;final TextEditingController? controller;final String? placeholder,error;final ValueChanged<String>? onChanged;final bool obscureText,enabled;final TextInputType? keyboardType;
 const KitTextField({super.key,required this.label,this.controller,this.placeholder,this.error,this.onChanged,this.obscureText=false,this.enabled=true,this.keyboardType});
 @override Widget build(BuildContext context)=>Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(label,style:const TextStyle(fontSize:13,color:CupertinoColors.secondaryLabel)),const SizedBox(height:8),CupertinoTextField(controller:controller,placeholder:placeholder,onChanged:onChanged,obscureText:obscureText,enabled:enabled,keyboardType:keyboardType,padding:const EdgeInsets.all(12),decoration:BoxDecoration(color:CupertinoColors.tertiarySystemFill.resolveFrom(context),borderRadius:BorderRadius.circular(12),border:error==null?null:Border.all(color:KitTheme.red))),if(error!=null)Text(error!,style:const TextStyle(color:KitTheme.red,fontSize:13))]);
}
class KitSlider extends StatelessWidget {final double value,min,max;final ValueChanged<double>? onChanged;final String label;const KitSlider({super.key,required this.value,required this.onChanged,required this.label,this.min=0,this.max=100});@override Widget build(BuildContext context)=>Semantics(label:label,child:CupertinoSlider(value:value.clamp(min,max),min:min,max:max,onChanged:onChanged,activeColor:KitTheme.blue));}
class KitStepper extends StatelessWidget {final int value,min,max,step;final ValueChanged<int> onChanged;const KitStepper({super.key,required this.value,required this.onChanged,this.min=0,this.max=100,this.step=1});@override Widget build(BuildContext context)=>DecoratedBox(decoration:BoxDecoration(color:CupertinoColors.tertiarySystemFill.resolveFrom(context),borderRadius:BorderRadius.circular(100)),child:Row(mainAxisSize:MainAxisSize.min,children:[IconButton(tooltip:'Decrease',onPressed:value<=min?null:()=>onChanged((value-step).clamp(min,max)),icon:const Icon(CupertinoIcons.minus)),Text('$value'),IconButton(tooltip:'Increase',onPressed:value>=max?null:()=>onChanged((value+step).clamp(min,max)),icon:const Icon(CupertinoIcons.plus))]));}
class KitSegmentedControl extends StatelessWidget {final Map<String,String> options;final String value;final ValueChanged<String> onChanged;const KitSegmentedControl({super.key,required this.options,required this.value,required this.onChanged});@override Widget build(BuildContext context)=>CupertinoSlidingSegmentedControl<String>(groupValue:value,children:options.map((k,v)=>MapEntry(k,Padding(padding:const EdgeInsets.symmetric(horizontal:12,vertical:6),child:Text(v)))),onValueChanged:(v){if(v!=null)onChanged(v);});}
class KitPageControl extends StatelessWidget {final int count,value;final ValueChanged<int> onChanged;const KitPageControl({super.key,required this.count,required this.value,required this.onChanged});@override Widget build(BuildContext context)=>Row(mainAxisSize:MainAxisSize.min,children:List.generate(count,(i)=>Semantics(label:'Page ${i+1}',selected:value==i,child:GestureDetector(onTap:()=>onChanged(i),child:Padding(padding:const EdgeInsets.all(8),child:Container(width:8,height:8,decoration:BoxDecoration(shape:BoxShape.circle,color:i==value?CupertinoColors.label.resolveFrom(context):CupertinoColors.tertiaryLabel.resolveFrom(context))))))));}
class KitProgressIndicator extends StatelessWidget {final double? value;const KitProgressIndicator({super.key,this.value});@override Widget build(BuildContext context)=>value==null?const CupertinoActivityIndicator():LinearProgressIndicator(value:value!.clamp(0,1),color:KitTheme.blue,borderRadius:BorderRadius.circular(100));}
class KitEmptyState extends StatelessWidget {final String title;final String? description;final Widget? icon,action;const KitEmptyState({super.key,required this.title,this.description,this.icon,this.action});@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(32),child:Column(mainAxisSize:MainAxisSize.min,children:[if(icon!=null)icon!,const SizedBox(height:16),Text(title,style:const TextStyle(fontSize:22,fontWeight:FontWeight.w600),textAlign:TextAlign.center),if(description!=null)Padding(padding:const EdgeInsets.only(top:8,bottom:16),child:Text(description!,textAlign:TextAlign.center,style:const TextStyle(fontSize:15))),if(action!=null)action!]));}
class KitListRow extends StatelessWidget {final String title;final String? subtitle;final Widget? leading,trailing;final VoidCallback? onTap;const KitListRow({super.key,required this.title,this.subtitle,this.leading,this.trailing,this.onTap});@override Widget build(BuildContext context)=>CupertinoListTile(title:Text(title),subtitle:subtitle==null?null:Text(subtitle!),leading:leading,trailing:trailing,onTap:onTap);}
class KitNotification extends StatelessWidget {final String title,body;final VoidCallback? onDismiss;const KitNotification({super.key,required this.title,required this.body,this.onDismiss});@override Widget build(BuildContext context)=>Semantics(liveRegion:true,child:Container(padding:const EdgeInsets.all(16),decoration:BoxDecoration(color:CupertinoColors.secondarySystemBackground.resolveFrom(context),borderRadius:BorderRadius.circular(24)),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontWeight:FontWeight.w600)),Text(body)])),if(onDismiss!=null)IconButton(tooltip:'Dismiss',onPressed:onDismiss,icon:const Icon(CupertinoIcons.xmark))])));}
class KitAction {final String label;final VoidCallback onSelected;final bool destructive;const KitAction(this.label,this.onSelected,{this.destructive=false});}
Future<void> showKitAlert(BuildContext context,{required String title,String? message,List<KitAction> actions=const []})=>showCupertinoDialog<void>(context:context,builder:(ctx)=>CupertinoAlertDialog(title:Text(title),content:message==null?null:Text(message),actions:actions.isEmpty?[CupertinoDialogAction(onPressed:()=>Navigator.pop(ctx),child:const Text('OK'))]:actions.map((a)=>CupertinoDialogAction(isDestructiveAction:a.destructive,onPressed:(){Navigator.pop(ctx);a.onSelected();},child:Text(a.label))).toList()));
Future<void> showKitActionSheet(BuildContext context,{required String title,required List<KitAction> actions})=>showCupertinoModalPopup<void>(context:context,builder:(ctx)=>CupertinoActionSheet(title:Text(title),actions:actions.map((a)=>CupertinoActionSheetAction(isDestructiveAction:a.destructive,onPressed:(){Navigator.pop(ctx);a.onSelected();},child:Text(a.label))).toList(),cancelButton:CupertinoActionSheetAction(onPressed:()=>Navigator.pop(ctx),child:const Text('Cancel'))));
Future<T?> showKitSheet<T>(BuildContext context,{required Widget child})=>showModalBottomSheet<T>(context:context,isScrollControlled:true,showDragHandle:true,shape:const RoundedRectangleBorder(borderRadius:BorderRadius.vertical(top:Radius.circular(32))),builder:(ctx)=>SafeArea(child:Padding(padding:EdgeInsets.only(bottom:MediaQuery.viewInsetsOf(ctx).bottom),child:child)));
class KitDatePicker extends StatelessWidget {final DateTime value;final ValueChanged<DateTime> onChanged;final CupertinoDatePickerMode mode;const KitDatePicker({super.key,required this.value,required this.onChanged,this.mode=CupertinoDatePickerMode.date});@override Widget build(BuildContext context)=>SizedBox(height:216,child:CupertinoDatePicker(initialDateTime:value,mode:mode,onDateTimeChanged:onChanged));}
class KitTabBar extends StatelessWidget {final List<BottomNavigationBarItem> items;final int value;final ValueChanged<int> onChanged;const KitTabBar({super.key,required this.items,required this.value,required this.onChanged});@override Widget build(BuildContext context)=>ClipRRect(borderRadius:BorderRadius.circular(32),child:CupertinoTabBar(items:items,currentIndex:value,onTap:onChanged,activeColor:KitTheme.blue));}
